        new Grzyb { Id = 63, Nazwa = "Czernidłak pospolity", Rodzina = "Kruchaweczkowate", Opis = "TRUJĄCY w połączeniu z alkoholem (zawiera kopryną blokującą metabolizm alkoholu). Bez alkoholu teoretycznie jadalny (młody).", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Coprinopsis_atramentaria.jpg?width=800" },
        new Grzyb { Id = 64, Nazwa = "Czernidłak błyszczący", Rodzina = "Kruchaweczkowate", Opis = "Rośnie kępami na pniach, a jego kapelusz pokryty jest błyszczącymi, mikowymi ziarenkami. Jadalne tylko białe formy młode.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Coprinellus_micaceus.jpg?width=800" },
        new Grzyb { Id = 65, Nazwa = "Lejkówka jadowita", Rodzina = "Gąskowate", Opis = "Mały, niepozorny biały grzyb rosnący na trawnikach i pastwiskach. Silnie trujący – zawiera muskarynę.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Clitocybe_dealbata.jpg?width=800" },
        new Grzyb { Id = 66, Nazwa = "Krowiak aksamitny", Rodzina = "Tapinellaceae", Opis = "Posiada masywny, brązowy, grubo zamszowy trzon boczny lub centralny. Rośnie na martwym drewnie. Niejadalny.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Tapinella_atrotomentosa.jpg?width=800" },
        new Grzyb { Id = 67, Nazwa = "Lisówka pomarańczowa", Rodzina = "Lisówkowate", Opis = "Nazywana potocznie 'fałszywą kurką'. Blaszki dużo drobniejsze, cienkie, kapelusz bywa jaskrawszy. Niejadalna.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Hygrophoropsis_aurantiaca.jpg?width=800" },
        new Grzyb { Id = 68, Nazwa = "Twardzioszek przydrożny", Rodzina = "Twardzioszkowate", Opis = "Rośnie w trawie tworząc słynne 'czarcie kręgi'. Ma mały kapelusz z garbem i bardzo twardy, elastyczny trzon.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Marasmius_oreades.jpg?width=800" },
        new Grzyb { Id = 69, Nazwa = "Twardzioszek czosnaczek", Rodzina = "Twardzioszkowate", Opis = "Drobniutki grzyb na igiełkowatym trzonie o potężnym, intensywnym zapachu czosnku. Wspaniały naturalny aromat do potraw.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Mycetinis_scorodonius.jpg?width=800" },
        new Grzyb { Id = 70, Nazwa = "Klejówka świerkowa", Rodzina = "Klejówkowate", Opis = "Kapelusz obficie pokryty grubym śluzem, który należy zerwać. Gotowany zmienia kolor na fioletowy.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Gomphidius_glutinosus.jpg?width=800" },
        new Grzyb { Id = 71, Nazwa = "Zasłonak fioletowy", Rodzina = "Zasłonakowate", Opis = "Wygląda zjawiskowo: jest od stóp do głów atramentowofioletowy. Jadalny, choć w Polsce rzadki.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Cortinarius_violaceus.jpg?width=800" },
        new Grzyb { Id = 72, Nazwa = "Purchawka gruszkowata", Rodzina = "Purchawkowate", Opis = "Ma gładką skórkę, rośnie licznie na martwym drewnie, a nie w ziemi. Jadalna dopóki biała w środku.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Apioperdon_pyriforme.jpg?width=800" },
        new Grzyb { Id = 73, Nazwa = "Czasznica olbrzymia", Rodzina = "Purchawkowate", Opis = "Biała, kulista purchawka osiągająca wielkość piłki. Wybitna na kotlety, gdy wnętrze jest idealnie białe.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Calvatia_gigantea.jpg?width=800" },
        new Grzyb { Id = 74, Nazwa = "Sromotnik smrodliwy", Rodzina = "Sromotnikowate", Opis = "W dorosłej formie wydziela odór wabiąc muchy. Młoda forma ('czarcie jajo') jest jadalna i stanowi rarytas.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Phallus_impudicus.jpg?width=800" },
        new Grzyb { Id = 75, Nazwa = "Żagiew łuskowa", Rodzina = "Żagwiowate", Opis = "Duża huba o zapachu świeżego ogórka lub arbuza. Pasożyt drzew liściastych. Młode owocniki są jadalne.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Cerioporus_squamosus.jpg?width=800" },
        new Grzyb { Id = 76, Nazwa = "Łuskwiak nastroszony", Rodzina = "Pierścieniakowate", Opis = "Pokryty sterczącymi łuskami. Występuje kępami u podnóży drzew. Gorzkawy, może wywołać niestrawność.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Pholiota_squarrosa.jpg?width=800" },
        new Grzyb { Id = 77, Nazwa = "Ucho bzowe", Rodzina = "Uszakowate", Opis = "Często nazywany 'grzybem Mun'. Elastyczny, rośnie głównie zimą na gałęziach czarnego bzu.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Auricularia_auricula-judae.jpg?width=800" },
        new Grzyb { Id = 78, Nazwa = "Żółciak siarkowy", Rodzina = "Żagwiowate", Opis = "Półki w jaskrawożółtym kolorze. Potocznie 'leśny kurczak' bo smażony mocno go przypomina (jadalny młody).", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Laetiporus_sulphureus.jpg?width=800" },
        new Grzyb { Id = 79, Nazwa = "Maślanka łagodna", Rodzina = "Pierścieniakowate", Opis = "W odróżnieniu od trującej maślanki wiązkowej ma rdzawy kapelusz i łagodny smak. Dobry grzyb na przetwory.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Hypholoma_capnoides.jpg?width=800" },
