        new Grzyb { Id = 101, Nazwa = "Goździeniec fioletowy", Rodzina = "Goździeńcowate", Opis = "Delikatny, ametystowo-fioletowy grzyb rosnący na trawnikach w postaci kruchych paluszków.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Clavaria_zollingeri.jpg?width=800" },
