        new Grzyb { Id = 119, Nazwa = "Koźlarz dębowy", Rodzina = "Borowikowate", Opis = "Szlachetny koźlarz rosnący zazwyczaj blisko dębów, tworzący piękne, masywne, ceglasto-brązowe owocniki.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Leccinum_quercinum.jpg?width=800" },
        new Grzyb { Id = 120, Nazwa = "Koźlarz świerkowy", Rodzina = "Borowikowate", Opis = "Kolejny reprezentant grupy czerwonych koźlarzy. Związany ze świerkami, jego czarne łuseczki gęsto pokrywają trzon.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Leccinum_piceinum.jpg?width=800" },
        new Grzyb { Id = 121, Nazwa = "Koźlarz sosnowy", Rodzina = "Borowikowate", Opis = "Rośnie głównie na piaszczystych glebach. Bardzo smaczny grzyb rzadziej spotykany od innych gatunków z rodziny.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Leccinum_vulpinum.jpg?width=800" },
        new Grzyb { Id = 122, Nazwa = "Koźlarz białawy", Rodzina = "Borowikowate", Opis = "Wyjątkowy grzyb bagienny posiadający prawie całkowicie biały lub seledynowy kapelusz. Miąższ jest nieco wodnisty.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Leccinum_holopus.jpg?width=800" },
        new Grzyb { Id = 123, Nazwa = "Hubiak pospolity", Rodzina = "Żagwiowate", Opis = "Stwardniała na kamień huba na pniach starych brzóz. Wykorzystywana wieki temu jako naturalna podpałka z krzesiwem.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Fomes_fomentarius.jpg?width=800" },
        new Grzyb { Id = 124, Nazwa = "Pniarek owczy", Rodzina = "Naziemkowate", Opis = "Jasny, twardy, pofałdowany grzyb rosnący prosto z ziemi na zboczach górskich, bardzo smaczny marynowany.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Albatrellus_ovinus.jpg?width=800" },
        new Grzyb { Id = 125, Nazwa = "Pniarek lekarski", Rodzina = "Pniarkowate", Opis = "Pasożyt modrzewi stosowany przez setki lat w medycynie. Ma gorzki miąższ. Dziś skrajnie rzadki w naturalnym środowisku.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Fomitopsis_officinalis.jpg?width=800" },
        new Grzyb { Id = 126, Nazwa = "Pniarek obrzeżony", Rodzina = "Pniarkowate", Opis = "Posiada jaskrawą, pomarańczowo-czerwoną obwódkę krawędzi. Często można na niej dostrzec duże, spływające krople płynu.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Fomitopsis_pinicola.jpg?width=800" },
        new Grzyb { Id = 127, Nazwa = "Wrośniak różnobarwny", Rodzina = "Żagwiowate", Opis = "Grzyb porastający kłody w formie pięknych rozetek (tzw. ogon indyka). Przebadany medycznie, jednak zbyt twardy by zjeść.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Trametes_versicolor.jpg?width=800" },
        new Grzyb { Id = 128, Nazwa = "Wrośniak szorstki", Rodzina = "Żagwiowate", Opis = "Blady, nadrzewny owocnik, którego wierzchnia warstwa jest bardzo wyraźnie, szorstko owłosiona niczym szczotka.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Trametes_hirsuta.jpg?width=800" },
        new Grzyb { Id = 129, Nazwa = "Błyskoporek podkorowy", Rodzina = "Szczeciniakowate", Opis = "Znany jako grzyb Chaga. Z zewnątrz przypomina zwęglenie drewna. Parzy się z niego cenne i zdrowe napary przeciwutleniające.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Inonotus_obliquus.jpg?width=800" },
        new Grzyb { Id = 130, Nazwa = "Żagwica listkowata", Rodzina = "Wachlarzowcowate", Opis = "Tworzy imponujące, kuliste, wielokilogramowe skupiska kapeluszy przy dębach. Japończycy nazywają ją grzybem Maitake.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Grifola_frondosa.jpg?width=800" },
        new Grzyb { Id = 131, Nazwa = "Lakownica żółtawa", Rodzina = "Lakownicowate", Opis = "Grzyb o twardym, czerwonym trzonku wyglądającym jak polakierowane rzeźbione drewno (Reishi). Powszechny w ziołolecznictwie.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Ganoderma_lucidum.jpg?width=800" },
        new Grzyb { Id = 132, Nazwa = "Lakownica spłaszczona", Rodzina = "Lakownicowate", Opis = "Płaski, dyskowaty grzyb tworzący półki na drzewach liściastych. Jego śnieżnobiały, gładki spód czernieje nawet przy lekkim nacisku.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Ganoderma_applanatum.jpg?width=800" },
        new Grzyb { Id = 133, Nazwa = "Białoporek brzozowy", Rodzina = "Pniarkowate", Opis = "Wygląda jak wypukła, puszysta poduszeczka osadzona na pniu brzóz. W przeszłości stosowano go do tamowania krwawień z ran.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Piptoporus_betulinus.jpg?width=800" },
        new Grzyb { Id = 134, Nazwa = "Kisielnica trzoneczkowa", Rodzina = "Uszakowate", Opis = "Po deszczu na patykach widać te miękkie, pofałdowane, czarne i galaretowate worki. Wyschnięte zlewają się z korą dębu.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Exidia_glandulosa.jpg?width=800" },
        new Grzyb { Id = 135, Nazwa = "Trzęsak pomarańczowożółty", Rodzina = "Trzęsakowate", Opis = "Fantastyczny galaretowaty, złocistożółty grzyb wyglądający często jak pomięta struktura mózgu na suchej, liściastej gałęzi.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Tremella_mesenterica.jpg?width=800" },
        new Grzyb { Id = 136, Nazwa = "Uszak skórnikowaty", Rodzina = "Uszakowate", Opis = "Blisko spokrewniony z Mun. Dolna strona grzyba przypomina fioletowo-brązowe użyłkowanie, górna jest matowa i włochata.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Auricularia_mesenterica.jpg?width=800" },
        new Grzyb { Id = 137, Nazwa = "Galaretek kolczasty", Rodzina = "Trzęsakowate", Opis = "Istne dziwactwo – kapelusik przypomina żelkę, ale na dolnej jego powierzchni wyrastają prawdziwe, półprzezroczyste kolce.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Pseudohydnum_gelatinosum.jpg?width=800" },
        new Grzyb { Id = 138, Nazwa = "Łuskwiak zmienny", Rodzina = "Pierścieniakowate", Opis = "Pyszny grzyb tworzący bogate kępy, ale zbierany z narażeniem życia – jest identyczny w wyglądzie z jadowitą hełmówką.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Kuehneromyces_mutabilis.jpg?width=800" },
        new Grzyb { Id = 139, Nazwa = "Łuskwiak złotawy", Rodzina = "Pierścieniakowate", Opis = "Rozwija żółtozłoty kapelusz z dużymi, ciemniejszymi łuskami tonącymi w wyraźnym śluzie. Silnie trujący.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Pholiota_aurivella.jpg?width=800" },
        new Grzyb { Id = 140, Nazwa = "Łysiczka lancetowata", Rodzina = "Kruchaweczkowate", Opis = "Drobny polny grzybek o stożkowatym kapeluszu. Jej posiadanie jest w Polsce zakazane ze względu na silną moc halucynogenną.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Psilocybe_semilanceata.jpg?width=800" },
        new Grzyb { Id = 141, Nazwa = "Hełmówka jadowita", Rodzina = "Hymenogastracae", Opis = "Śmiertelnie trujący owocnik pokryty żółtobrązowym kolorem rdzawym. Jej toksyny całkowicie zatrzymują syntezę białek w wątrobie.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Galerina_marginata.jpg?width=800" },
        new Grzyb { Id = 142, Nazwa = "Pierścieniak uprawny", Rodzina = "Pierścieniakowate", Opis = "Często celowo szczepiony w ogrodowych zrębkach i kompostownikach. Jego okazałe, bordowe owocniki bywają przysmakiem.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Stropharia_rugosoannulata.jpg?width=800" },
        new Grzyb { Id = 143, Nazwa = "Pierścieniak grynszpanowy", Rodzina = "Pierścieniakowate", Opis = "Wyróżnia się spośród innych unikalną niebiesko-zieloną, turkusową i niezwykle oślizgłą barwą z białymi płateczkami okrywy na brzegach.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Stropharia_aeruginosa.jpg?width=800" },
        new Grzyb { Id = 144, Nazwa = "Polówka zawoalowana", Rodzina = "Pierścieniakowate", Opis = "Jeden z pierwszych większych grzybów wiosny, wyrasta bardzo tłumnie w miejskich parkach i przydrożach pełnych kory.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Agrocybe_praecox.jpg?width=800" },
        new Grzyb { Id = 145, Nazwa = "Czasznica workowata", Rodzina = "Purchawkowate", Opis = "Stosunkowo duża biała purchawka o charakterystycznym trzonie rozszerzającym się ku górze niczym gruszka czy nabity worek.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Calvatia_excipuliformis.jpg?width=800" },
        new Grzyb { Id = 146, Nazwa = "Kurzawka czerniejąca", Rodzina = "Purchawkowate", Opis = "Skórzasta kulista kuleczka wyrastająca na suchych pastwiskach. Dorastając odłącza się od grzybni i czernieje, wydmuchując proszek.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Bovista_nigrescens.jpg?width=800" },
        new Grzyb { Id = 147, Nazwa = "Gwiazdosz frędzelkowaty", Rodzina = "Gwiazdoszowate", Opis = "Wygląda zniewalająco – jego gruba, rdzawa osłona pęka niczym szpikulce gwiazdy obnażając centralną kulistą zarodnię w środku mchu.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Geastrum_fimbriatum.jpg?width=800" },
        new Grzyb { Id = 148, Nazwa = "Gwiazdosz potrójny", Rodzina = "Gwiazdoszowate", Opis = "Duży, wielowarstwowy gwiazdosz, którego mięsiste pęknięte dno otacza główkę przypominając lądowanie statku obcych w ściółce leśnej.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Geastrum_triplex.jpg?width=800" },
        new Grzyb { Id = 149, Nazwa = "Sromotnik fiołkowy", Rodzina = "Sromotnikowate", Opis = "Wyłania się z ukrytego w piaskach wydm bańkowatego, bladofioletowego jaja. Przywabia padlinówki ostrym aromatem fetoru z rozkładu.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Phallus_hadriani.jpg?width=800" },
        new Grzyb { Id = 150, Nazwa = "Okratek australijski", Rodzina = "Sromotnikowate", Opis = "Przywleczony z krain kangurowych. Młode pęknięte jajo wyrzuca kilka krwistoczerwonych, mięsistych ramion w kształt morskiej ośmiornicy.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Clathrus_archeri.jpg?width=800" },
        new Grzyb { Id = 151, Nazwa = "Mądziak malinowy", Rodzina = "Sromotnikowate", Opis = "Stojący cienki trzon zakończony zaokrąglonym główką w kolorze malin, bardzo obficie pokrytą śluzem i muchami poszukującymi padliny.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Mutinus_ravenelii.jpg?width=800" },
        new Grzyb { Id = 152, Nazwa = "Piestrzenica olbrzymia", Rodzina = "Krążkownicowate", Opis = "Złotawo-żółta pofałdowana forma na kształt połówki potężnego mózgowia, rzadsza od piestrzenicy kasztanowatej, ale tak samo toksyczna.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Gyromitra_gigas.jpg?width=800" },
        new Grzyb { Id = 153, Nazwa = "Smardz stożkowaty", Rodzina = "Smardzowate", Opis = "Wiosenny unikat. Jego kapelusz ma wyraźnie wyciągnięty ku górze i spiczasty kształt szarego plastra wosku pszczelego.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Morchella_conica.jpg?width=800" },
        new Grzyb { Id = 154, Nazwa = "Smardz wyniosły", Rodzina = "Smardzowate", Opis = "Podobny do innych rzadkich smardzy, często związany ze zrębami w borach świerkowych – niesamowity w smaku na maśle po uduszeniu.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Morchella_elata.jpg?width=800" },
        new Grzyb { Id = 155, Nazwa = "Naparstniczka czeska", Rodzina = "Smardzowate", Opis = "Chroniona wiosenna główka, przypominająca dzwon lub kapturek tylko czubkiem przylegająca i nasunięta na bardzo długi, prosty trzon.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Verpa_bohemica.jpg?width=800" },
        new Grzyb { Id = 156, Nazwa = "Kustrzebka pomarańczowa", Rodzina = "Kustrzebkowate", Opis = "Nieregularne miseczki lub kraterki leżące na gołej, zruszonej ziemi lasu. Biją po oczach neonowo jarzącą pomarańczową barwą na duże odległości.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Aleuria_aurantia.jpg?width=800" },
        new Grzyb { Id = 157, Nazwa = "Kustrzebka pęcherzykowata", Rodzina = "Kustrzebkowate", Opis = "Zwykłe cienkie jasnobrązowe pucharki zbierające się dużymi stłoczeniami w kompostownikach z obornikiem i przegnitym nawozem.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Peziza_vesiculosa.jpg?width=800" },
        new Grzyb { Id = 158, Nazwa = "Pięknóg żółty", Rodzina = "Łzawnikowate", Opis = "Mały, sprężysty grzybek wypuszczający intensywnie jaskrawe, złocistożółte zaostrzone rogi prosto z zagrzebanych gałęzi drzew iglastych.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Calocera_viscosa.jpg?width=800" },
        new Grzyb { Id = 159, Nazwa = "Buławka obcięta", Rodzina = "Buławkowate", Opis = "Miąższ ukształtowany w dużą, zwężającą się pomarańczową pałkę, jakby uciętą od góry równo tasakiem tworząc gładką, stołową platformę.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Clavariadelphus_truncatus.jpg?width=800" },
        new Grzyb { Id = 160, Nazwa = "Szmaciak dębowy", Rodzina = "Siedzuniowate", Opis = "Podobny do siedzuń sosnowego z tym wyjątkiem, że jest dużo bardziej gładki z wyraźnymi liściastymi wstążkami, wyrasta przy pniach dębu.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Sparassis_brevipes.jpg?width=800" },
        new Grzyb { Id = 161, Nazwa = "Tęgoskór cytrynowy", Rodzina = "Tęgoskórowate", Opis = "Skórzasta, pękata purchawka na wierzchu bladożółtawa ze spękaniami w łuski, jej miąższ od początku dojrzewania jest sadzasto, atramentowo czarny.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Scleroderma_citrinum.jpg?width=800" },
        new Grzyb { Id = 162, Nazwa = "Tęgoskór pospolity", Rodzina = "Tęgoskórowate", Opis = "Posiada dużo dłuższy i grubszy trzonek niż tęgoskór cytrynowy a okrywa brązowawa jest pełna drobnych brodawek. Wybitnie nienadający się do jedzenia.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Scleroderma_verrucosum.jpg?width=800" },
        new Grzyb { Id = 163, Nazwa = "Płomiennica letnia", Rodzina = "Fizalakowate", Opis = "Wydaje bledsze i cieńsze kapelusze niż swoja zimowa znana wszystkim siostra, występując gęstą rojadą po ulewnych, ciepłych deszczach na liściastych wywrotach.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Flammulina_fennae.jpg?width=800" },
        new Grzyb { Id = 164, Nazwa = "Boczniak łyżkowaty", Rodzina = "Boczniakowate", Opis = "Częsty letni przysmak. O wiele cieńszy, niemal biały owocnik o budowie łopatek opanowujący stare drzewa osikowe wokół bagiennych terenów.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Pleurotus_pulmonarius.jpg?width=800" },
        new Grzyb { Id = 165, Nazwa = "Twardziak muszlowy", Rodzina = "Żagwiowate", Opis = "Bardzo mocno oporny twardy grzyb rosnący głównie na wierzbowym drewnie o łuskowatym rudym kapeluszu i fioletowawym puszku u nasady.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Lentinus_conchatus.jpg?width=800" },
        new Grzyb { Id = 166, Nazwa = "Żyłkowiec różowawy", Rodzina = "Fizalakowate", Opis = "Nieprawdopodobny leśny wizerunek krwisto różowej siatki gęstych żył, wypiętrzających całą galaretowatą powierzchnię tego dziwnego kapelusza wiązkami nerwów.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Rhodotus_palmatus.jpg?width=800" },
        new Grzyb { Id = 167, Nazwa = "Gąsówka dwubarwna", Rodzina = "Gąskowate", Opis = "Jej mocny liliowo-fioletowy krótki gruby pniak mocno odcina się od całkowicie brązowego matowego i płaskiego wielkiego kapelusza w trawiastych dąbrowach.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Lepista_personata.jpg?width=800" },
        new Grzyb { Id = 168, Nazwa = "Kępkowiec jasnobrązowy", Rodzina = "Kępkowcowate", Opis = "Rosną w potężnych pęczkach ściśnięte łodyżkami i elastyczne grzyby o ziemnych barwach wzdłuż ścieżek, bardzo cenne po dobrym wysmażeniu.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Lyophyllum_decastes.jpg?width=800" },
        new Grzyb { Id = 169, Nazwa = "Czubajka czerwieniejąca", Rodzina = "Pieczarkowate", Opis = "Grzyb w skali niemal kopiujący pyszną kanię, jednak gładka i bulwiasta od spodu łodyga wraz z błyskawicznym brunatnym krwawieniem odłamków każe zachować ostrożność trawienną.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Chlorophyllum_rhacodes.jpg?width=800" },
        new Grzyb { Id = 170, Nazwa = "Muchomor narcyzowy", Rodzina = "Muchomorowate", Opis = "Truciciel wyglądający niczym rozpuszczona wersja swego plamistego kuzyna o mocno mylącym musztardowożółtym odcieniu ze szczątkami białych łat.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Amanita_gemmata.jpg?width=800" },
        new Grzyb { Id = 171, Nazwa = "Gołąbek brunatny", Rodzina = "Gołąbkowate", Opis = "Jego duża lśniąca tarcza po zjedzeniu małego surowego kawałka blaszki nieziemsko zaczyna piec w usta pozostawiając zgagę jeszcze przez parę godzin od wyplucia.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Russula_badia.jpg?width=800" },
        new Grzyb { Id = 172, Nazwa = "Gołąbek brzozowy", Rodzina = "Gołąbkowate", Opis = "Słaby gatunek, którego różowawa malutka główka po dotknięciu deszczu od razu blaknie niemal na biało; mocno łamliwy i paląco gorzki.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Russula_betularum.jpg?width=800" },
        new Grzyb { Id = 173, Nazwa = "Gołąbek płowiejący", Rodzina = "Gołąbkowate", Opis = "Rude cudo iglastych puszcz, twardy gruby korzeń po naruszeniu oraz ugotowaniu drastycznie ciemnieje tracąc barwę lecz dając fenomenalny posmak grzybowy.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Russula_decolorans.jpg?width=800" },
        new Grzyb { Id = 174, Nazwa = "Mleczaj zieleniejący", Rodzina = "Gołąbkowate", Opis = "Wydziela mnóstwo piekącego pieprznego białego soku z blaszek, a kapelusz powlekany jest oliwkowozielonym, bardzo gęstym kleistym lepiszczem.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Lactarius_blennius.jpg?width=800" },
        new Grzyb { Id = 175, Nazwa = "Mleczaj liliowy", Rodzina = "Gołąbkowate", Opis = "Śliczna sucha struktura pokryta drobinkami w rzadkim różowo-szaro-liliowym kolorze w sąsiedztwie korzeni starej olchy.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Lactarius_lilacinus.jpg?width=800" },
        new Grzyb { Id = 176, Nazwa = "Mleczaj siarkowy", Rodzina = "Gołąbkowate", Opis = "Odróżnia się tym że jakikolwiek ubytek ciała wytacza z niego początkowo czyste białe mleczko by dosłownie na naszych oczach zabarwić je na gryząco żółtą siarkę.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Lactarius_chrysorrheus.jpg?width=800" },
        new Grzyb { Id = 177, Nazwa = "Mleczaj bladawy", Rodzina = "Gołąbkowate", Opis = "Mięsisty i bardzo uginający się, blado kremowy okrąg posypany silnym śluzem, pojawiający się wybitnie masowo przy samych korzeniach gładkich dorosłych buków.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Lactarius_pallidus.jpg?width=800" },
        new Grzyb { Id = 178, Nazwa = "Gąska rdzawobrązowa", Rodzina = "Gąskowate", Opis = "Jesienny symbol leśny spod brzezin o ciemnokasztanowym lepkim centrum kapelusza wyczuwalnie pachnący mieszanką mąki i siana.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Tricholoma_fulvum.jpg?width=800" },
        new Grzyb { Id = 179, Nazwa = "Gąska zielonożółta", Rodzina = "Gąskowate", Opis = "Z przerażeniem omijana chociaż piękna. Kolorystyką oraz promienistymi zielonawymi żyłkami złudnie przebiera się za strasznego muchomora sromotnika.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Tricholoma_sejunctum.jpg?width=800" },
        new Grzyb { Id = 180, Nazwa = "Gąska dachówkowata", Rodzina = "Gąskowate", Opis = "Brązowo miedziany owocnik którego skórka spękała we wzory bardzo przylegających do siebie łuseczek udając nakładane dachówki rzymskiego domu.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Tricholoma_imbricatum.jpg?width=800" },
        new Grzyb { Id = 181, Nazwa = "Gołąbek białawy", Rodzina = "Gołąbkowate", Opis = "Duży, twardy białawy grzyb z kraterkowatym kapeluszem, wydzielający słaby zapach śledzi lub owoców morza. Na ogół niejadalny.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Russula_delica.jpg?width=800" },
        new Grzyb { Id = 182, Nazwa = "Gołąbek śmierdzący", Rodzina = "Gołąbkowate", Opis = "Żółtobrązowy kapelusz powleczony mocnym śluzem, z daleka wydziela silny, wybitnie odpychający zapach zjełczałego oleju.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Russula_foetens.jpg?width=800" },
        new Grzyb { Id = 183, Nazwa = "Gołąbek czarniawy", Rodzina = "Gołąbkowate", Opis = "Masywny gołąbek. Po przecięciu jego jasny miąższ czerwienieje, a potem robi się smoliście, węglisto czarny.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Russula_nigricans.jpg?width=800" },
        new Grzyb { Id = 184, Nazwa = "Gołąbek złotawy", Rodzina = "Gołąbkowate", Opis = "Przepiękny grzyb o pomarańczowo-czerwonym kapeluszu i intensywnie cytrynowożółtych blaszkach pod spodem. Bardzo smaczny.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Russula_aurata.jpg?width=800" },
        new Grzyb { Id = 185, Nazwa = "Gołąbek słodkawy", Rodzina = "Gołąbkowate", Opis = "Kapelusz o zmiennej, ciemnowinnej barwie. Cechuje się łagodnym i słodkawym miąższem przypominającym orzechy.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Russula_integra.jpg?width=800" },
        new Grzyb { Id = 186, Nazwa = "Gołąbek cukrówka", Rodzina = "Gołąbkowate", Opis = "Duży czerwony gołąbek rosnący głównie na mokradłach i bagnach. Posiada słodkawy smak i twardy trzon.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Russula_paludosa.jpg?width=800" },
        new Grzyb { Id = 187, Nazwa = "Gołąbek różowy", Rodzina = "Gołąbkowate", Opis = "Niewielki, matowy i pudrowy owocnik o pięknej karminowej barwie. Ze względu na wiórowatą strukturę, mało atrakcyjny kulinarnie.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Russula_rosea.jpg?width=800" },
        new Grzyb { Id = 188, Nazwa = "Mleczaj dębowy", Rodzina = "Gołąbkowate", Opis = "Bardzo pospolity pod dębami grzyb wydzielający zapach roztartych liści dębu lub... pluskwiaków. Traci nieprzyjemny aromat po ugotowaniu.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Lactarius_quietus.jpg?width=800" },
        new Grzyb { Id = 189, Nazwa = "Mleczaj jodłowy", Rodzina = "Gołąbkowate", Opis = "Brat rydza, rosnący jednak wyłącznie pod jodłami. Po uszkodzeniu toczy marchewkowe mleczko, które wolno blednie.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Lactarius_salmonicolor.jpg?width=800" },
        new Grzyb { Id = 190, Nazwa = "Mleczaj dołkowany", Rodzina = "Gołąbkowate", Opis = "Duży mleczaj o słomkowym kolorze i bardzo charakterystycznych 'wyżartych' ciemnych dołkach na całym trzonie. Lekko trujący.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Lactarius_scrobiculatus.jpg?width=800" },
        new Grzyb { Id = 191, Nazwa = "Mleczaj płowy", Rodzina = "Gołąbkowate", Opis = "Jasnobrązowy grzyb bagienny wydzielający silny zapach przyprawy maggi. Ze względu na toksyny zalecany najwyżej jako przyprawa.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Lactarius_helvus.jpg?width=800" },
        new Grzyb { Id = 192, Nazwa = "Mleczaj chrząstka", Rodzina = "Gołąbkowate", Opis = "Jeden z najtwardszych grzybów blaszkowych. Duży, biały, wydzielający piekące mleczko. Niemal jak chrząstka przy krojeniu.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Lactarius_vellereus.jpg?width=800" },
        new Grzyb { Id = 193, Nazwa = "Strzępiak ceglasty", Rodzina = "Strzępiakowate", Opis = "Śmiertelnie trujący owocnik wyrastający w parkach latem. Jego stożkowaty kapelusz pod dotykiem nabiera ceglastej, czerwonej barwy.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Inocybe_erubescens.jpg?width=800" },
        new Grzyb { Id = 194, Nazwa = "Strzępiak pospolity", Rodzina = "Strzępiakowate", Opis = "Maleńki, fioletowawy lub biały grzybek ze stożkiem, pachnący jak surowy, gnijący ziemniak. Bardzo niebezpieczny.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Inocybe_geophylla.jpg?width=800" },
        new Grzyb { Id = 195, Nazwa = "Strzępiak rzepowaty", Rodzina = "Strzępiakowate", Opis = "Brązowy grzybek iglasty którego trzon na samym dole jest charakterystycznie zgrubiały niczym miniaturowa rzepa.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Inocybe_napipes.jpg?width=800" },
        new Grzyb { Id = 196, Nazwa = "Zasłonak gliniasty", Rodzina = "Zasłonakowate", Opis = "Trzon tego brązowego grzyba pokryty jest śluzowatymi obrączkami, tworzącymi schodkowaty wzór przypominający mokrą glinę.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Cortinarius_trivialis.jpg?width=800" },
        new Grzyb { Id = 197, Nazwa = "Zasłonak niebieskawy", Rodzina = "Zasłonakowate", Opis = "Atrakcyjny owocnik, którego młode kapelusze powlekane są lśniącym, głębokim błękitem przechodzącym z wiekiem w ochrę.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Cortinarius_caerulescens.jpg?width=800" },
        new Grzyb { Id = 198, Nazwa = "Zasłonak śluzowaty", Rodzina = "Zasłonakowate", Opis = "Rośnie w igliwiu sosnowym. Bardzo pękaty, a jego trzon i kapelusz wręcz ociekają grubą, bezbarwną warstwą galaretowatego śluzu.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Cortinarius_mucosus.jpg?width=800" },
        new Grzyb { Id = 199, Nazwa = "Zasłonak anyżkowy", Rodzina = "Zasłonakowate", Opis = "Zielono-żółty grzyb z bulwiastym trzonem. Przełamany wydziela zjawiskowo mocny zapach anyżu, lukrecji lub kopru.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Cortinarius_odorifer.jpg?width=800" },
