        new Grzyb { Id = 201, Nazwa = "Pieczarka bulwiasta", Rodzina = "Pieczarkowate", Opis = "Wysoka, leśna pieczarka, której trzon zakończony jest widoczną asymetryczną bulwą. Wydziela miły zapach migdałów.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Agaricus_abruptibulbus.jpg?width=800" },
        new Grzyb { Id = 202, Nazwa = "Pieczarka okazała", Rodzina = "Pieczarkowate", Opis = "Ogromna pieczarka leśna pokryta drobnymi, żółtobrązowymi łuseczkami. Smakuje wybornie, a pachnie jak słodkie marcepany.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Agaricus_augustus.jpg?width=800" },
        new Grzyb { Id = 203, Nazwa = "Pieczarka krwawiąca", Rodzina = "Pieczarkowate", Opis = "Szlachetna leśna pieczarka. Przekrojenie nożem jej miąższu wywołuje natychmiastowe wytoczenie soków barwy krwistej.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Agaricus_langei.jpg?width=800" },
