        new Grzyb { Id = 205, Nazwa = "Czubajeczka brązowooliwkowa", Rodzina = "Pieczarkowate", Opis = "Śmiertelnie trujący grzyb mylony z malutką kanią! Zawiera tę samą truciznę co sromotnik – amanitynę niszczącą wątrobę.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Lepiota_brunneoincarnata.jpg?width=800" },
