        new Grzyb { Id = 207, Nazwa = "Czubajka gwiaździsta", Rodzina = "Pieczarkowate", Opis = "Smaczna kania łąkowa. Rozpoznawana po tym, że skórka na kapeluszu pęka tworząc idealną, gładką brązową gwiazdę na samym środku.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Macrolepiota_excoriata.jpg?width=800" },
