        new Grzyb { Id = 211, Nazwa = "Wilgotnica śnieżna", Rodzina = "Wodnichowate", Opis = "W całości szklisto-biały, na wpół przezroczysty grzybek wilgotnych, czystych trawników i łąk o delikatnym smaku.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Cuphophyllus_virgineus.jpg?width=800" },
        new Grzyb { Id = 212, Nazwa = "Grzybówka czysta", Rodzina = "Grzybówkowate", Opis = "Dzwonkowaty fioletowy owocnik masowo zrzucający biały pył i silnie pachnący białą rzodkwią. Trujący, halucynogenny.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Mycena_pura.jpg?width=800" },
        new Grzyb { Id = 213, Nazwa = "Grzybówka różowa", Rodzina = "Grzybówkowate", Opis = "Brat grzybówki czystej o oszałamiającym, intensywnie landrynkowym, jasnoróżowym kolorze. Toksyczna.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Mycena_rosea.jpg?width=800" },
        new Grzyb { Id = 214, Nazwa = "Grzybówka alkaliczna", Rodzina = "Grzybówkowate", Opis = "Szara chudziutka parasolka porastająca pniaki sosny, której roztarty miąższ uderza w nozdrza ostrym smrodem chloru z amoniakiem.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Mycena_stipata.jpg?width=800" },
        new Grzyb { Id = 215, Nazwa = "Purchawka jeżowata", Rodzina = "Purchawkowate", Opis = "Rosnąca w liściach urocza, okrągła brązowa purchawka naszpikowana długimi, zgiętymi, ciemnymi kolcami zbiegającymi się w piramidki.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Lycoperdon_echinatum.jpg?width=800" },
