        new Grzyb { Id = 217, Nazwa = "Kurzawka ołowiana", Rodzina = "Purchawkowate", Opis = "Brak klasycznego trzonu. Jej powierzchnia do złudzenia przypomina obrobioną rzemieślniczo szarą, metalową, ołowianą bilę leżącą na łące.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Bovista_plumbea.jpg?width=800" },
        new Grzyb { Id = 218, Nazwa = "Pałeczka włośniowata", Rodzina = "Pieczarkowate", Opis = "Maleńka, niesamowita konstrukcja – brązowa główeczka wzniesiona na cienkiej i długiej wykałaczce wystająca z piaszczystych mchów z otworem na czubku.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Tulostoma_brumale.jpg?width=800" },
        new Grzyb { Id = 219, Nazwa = "Piestrzyca kędzierzawa", Rodzina = "Piestrzycowate", Opis = "Bardzo wykręcony jesienny owocnik w białym kolorze, o kapeluszu sfałdowanym jak prześcieradło i trzonku pełnym głębokich bruzd i dziur.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Helvella_crispa.jpg?width=800" },
        new Grzyb { Id = 220, Nazwa = "Piestrzyca czarna", Rodzina = "Piestrzycowate", Opis = "Posiada równie poszarpany, pognieciony w rurkę biały trzon co jej siostra, ale sama główka wygląda jak nieregularna grudka smoły.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Helvella_lacunosa.jpg?width=800" },
        new Grzyb { Id = 221, Nazwa = "Piestrzyca giętka", Rodzina = "Piestrzycowate", Opis = "Elegancki i subtelny jasnobrązowy grzybek w kształcie siodła narzuconego na gładki, biały i elastyczny niczym makaron pręcik.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Helvella_elastica.jpg?width=800" },
        new Grzyb { Id = 222, Nazwa = "Kolczakówka piekąca", Rodzina = "Kolcownicowate", Opis = "Niezwykły widok: podczas wilgoci ten kolczasty grzyb uwalnia przez pory na swym kapeluszu gęste krople krwistoczerwonej cieczy. Paląco piekąca, niejadalna.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Hydnellum_peckii.jpg?width=800" },
        new Grzyb { Id = 223, Nazwa = "Kolczakówka niebieskawa", Rodzina = "Kolcownicowate", Opis = "Gruby twardy owocnik wyrastający między szyszkami i igliwiem charakteryzujący się mocnymi błękitno-stalowymi zamszowymi strefami rosnącymi u krawędzi.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Hydnellum_caeruleum.jpg?width=800" },
