        new Grzyb { Id = 225, Nazwa = "Wachlarzowiec olbrzymi", Rodzina = "Wachlarzowcowate", Opis = "Potwornej wielkości płaty wyrastające przy pniach buków. Złamane lub poszarpane jego żółtawe liście błyskawicznie ciemnieją na smolisto-czarno.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Meripilus_giganteus.jpg?width=800" },
        new Grzyb { Id = 226, Nazwa = "Murszak rdzawy", Rodzina = "Murszakowate", Opis = "Ciemnordzawy niszczyciel korzeni iglastych wyrastający w pobliżu pni sosny niczym wielka miękka, poduszkowata brunatna gąbka z żółtym rantem.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Phaeolus_schweinitzii.jpg?width=800" },
        new Grzyb { Id = 227, Nazwa = "Gmatwek dębowy", Rodzina = "Pniarkowate", Opis = "Wypukła huba na ściętym dębowym drewnie której spodnie rurki rozrosły się w bardzo długie, zawiłe i poplątane w labirynt listewki.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Daedalea_quercina.jpg?width=800" },
        new Grzyb { Id = 228, Nazwa = "Wrośniak anyżkowy", Rodzina = "Żagwiowate", Opis = "Bielutki poduszkowaty grzyb opanowujący gałęzie chorych wierzb. Ułamany z drzewa rozsiewa wkoło silny, apteczny odór kropel anyżowych.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Trametes_suaveolens.jpg?width=800" },
        new Grzyb { Id = 229, Nazwa = "Gęstoporek cynobrowy", Rodzina = "Żagwiowate", Opis = "Wygląda jak owalna, płaska poduszka ufarbowana na jaskrawo-cynobrowy odcień czerwonopomarańczowy. Rzuca się w oczy w lesie z kilkudziesięciu metrów.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Pycnoporus_cinnabarinus.jpg?width=800" },
        new Grzyb { Id = 230, Nazwa = "Błyskoporek dębowy", Rodzina = "Szczeciniakowate", Opis = "Masywna bryła pojawiająca się u stóp prastarych dębów we wspaniałym kasztanowym kolorze i obficie roniąca bursztynowe soki na całą swą powierzchnię.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Inonotus_dryadeus.jpg?width=800" },
        new Grzyb { Id = 231, Nazwa = "Borowik purpurowy", Rodzina = "Borowikowate", Opis = "Rzadki i trujący borowik z mocnym żółto-różowym trzonkiem ukrytym pod jasnym kapeluszem. Po przecięciu momentalnie robi się mocno niebiesko-atramentowy.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Rubroboletus_rhodoxanthus.jpg?width=800" },
        new Grzyb { Id = 232, Nazwa = "Borowik szkarłatny", Rodzina = "Borowikowate", Opis = "Egzotycznie wyglądający i bajecznie rzadki w Polsce, kapelusz u niego przypomina lśniącą czerwoną śliwkę narzuconą nad intensywnie czerwonymi rurkami.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Rubroboletus_dupainii.jpg?width=800" },
        new Grzyb { Id = 233, Nazwa = "Borowik gładkotrzonowy", Rodzina = "Borowikowate", Opis = "Wydaje gładki (bez widocznej siateczki) żóltoczerwonawy trzon i ciemne pory. Silnie zmienia kolor po roztarciu. Jadalny tylko bardzo dobrze wygotowany.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Suillellus_queletii.jpg?width=800" },
        new Grzyb { Id = 234, Nazwa = "Podgrzybek obciętozarodnikowy", Rodzina = "Borowikowate", Opis = "Odróżnia się tym że spękania na ciemnym brązowym kapeluszu nie pokazują różowych szczelin (jak u kuzynów) tylko głęboką szarą zamszową pleśń.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Xerocomellus_porosporus.jpg?width=800" },
        new Grzyb { Id = 235, Nazwa = "Wonnoborowik kruchy", Rodzina = "Borowikowate", Opis = "Mało znany rurkowy grzybek dębin wydający miły, owocowy zapach, a pod kapeluszem świecący się ostrym złotym odcieniem luźnych rurek, który z wiekiem zanika.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Aureoboletus_gentilis.jpg?width=800" },
        new Grzyb { Id = 236, Nazwa = "Zamszoborowik brzoskwiniowy", Rodzina = "Borowikowate", Opis = "Twardy mały owocnik u którego sam dół trzonka w głębi ziemi jest mocno pomarańczowo żółty, a podstawa gąbki potrafi zabarwiać się do koloru brzoskwiniowego.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Rheubarbariboletus_persicolor.jpg?width=800" },
        new Grzyb { Id = 237, Nazwa = "Maślak daglezjowy", Rodzina = "Maślakowate", Opis = "Ścisły symbiotyk sprowadzonych do nas drzew daglezjowych, mieniący się wielkimi rdzawymi łuskami pękniętymi na pomarańczowawym kapeluszu.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Suillus_lakei.jpg?width=800" },
        new Grzyb { Id = 238, Nazwa = "Maślak rdzawy", Rodzina = "Maślakowate", Opis = "Bywa mylony ze zwyczajnym ziarnistym, ma jednak na dnie łodygi (wyjętej z igieł sosny) zawsze mocne rdzawo-różowe plamy grzybniowe na nóżce.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Suillus_collinitus.jpg?width=800" },
        new Grzyb { Id = 239, Nazwa = "Koźlarz bruzdkowany", Rodzina = "Borowikowate", Opis = "Wybitny ciekawej barwy – jako jedyny z koźlarzy ma cały kapelusz i rurki w barwie złoto-żółtawej, ułożone na typowym chropowatym szarym koźlim trzonku.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Leccinum_crocipodium.jpg?width=800" },
        new Grzyb { Id = 240, Nazwa = "Koźlarz czarnobrązowy", Rodzina = "Borowikowate", Opis = "Najciemniejsza 'babka'. Spotykana z brzozami wyrzuca okazałe ciemnoczarne do brunatnych kapelusze wsparte o grubo obrośniętą na czarno nogę.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Leccinum_melaneum.jpg?width=800" },
        new Grzyb { Id = 241, Nazwa = "Koralówka blada", Rodzina = "Siostrzankowate", Opis = "Wielki gęsty grzyb przypominający koralowce o bledziutkim łososiowo-fioletowawym tonie, wyrastający w świerkowych igłach. Powoduje ostre, bardzo niebezpieczne zatrucia.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Ramaria_pallida.jpg?width=800" },
        new Grzyb { Id = 242, Nazwa = "Koralówka sztywna", Rodzina = "Siostrzankowate", Opis = "Puszysty gęsty i wysoki koralowiec wyrastający nie z ziemi ale zawsze na zmurszałym drewnie, o miąższu elastycznym i po dotknięciu przebarwiającym się rudo.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Ramaria_stricta.jpg?width=800" },
        new Grzyb { Id = 243, Nazwa = "Goździeniec robakowaty", Rodzina = "Goździeńcowate", Opis = "Masowy widok cieniutkich sztywnych kremowobiałych patyczków wybijających z niskiej mchowej łąki bez jakichkolwiek rozgałęzień czy kapeluszy.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Clavaria_fragilis.jpg?width=800" },
        new Grzyb { Id = 244, Nazwa = "Goździeniowiec miodowy", Rodzina = "Goździeńcowate", Opis = "Intensywnie żółciutkie samotne rureczki wyrastające na polanach jak słupy odblaskowe. Rzadki klejnocik łąk o bardzo mizernym, nienadającym się do kuchni ciele.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Clavulinopsis_helvola.jpg?width=800" },
        new Grzyb { Id = 245, Nazwa = "Kisielnica karmelowa", Rodzina = "Uszakowate", Opis = "Bursztynowa lub czerwonobrązowa wspaniała i pofałdowana galaretka roniąca grube liście prosto na uschłych cienkich gałązkach wierzbowych i brzozowych.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Exidia_recisa.jpg?width=800" },
        new Grzyb { Id = 246, Nazwa = "Łzawnik rozciekliwy", Rodzina = "Łzawnikowate", Opis = "Niesamowite żółto-pomarańczowe kleiste krople wybijające z pozbawionych kory suchych pni sosnowych na gołej, nagrzanej od jesiennego słońca belce.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Dacrymyces_stillatus.jpg?width=800" },
        new Grzyb { Id = 247, Nazwa = "Uszak gęstowłosy", Rodzina = "Uszakowate", Opis = "Bliski kuzyn klasycznych grzybów Mun, zewnętrzna górna powłoka jest twardo owłosiona ułatwiając przetrwanie suszy azjatyckiego stepu. Idealny do orientalnego chrupnięcia.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Auricularia_polytricha.jpg?width=800" },
        new Grzyb { Id = 248, Nazwa = "Skórnik szorstki", Rodzina = "Skórnikowate", Opis = "Twarda ucho podobna konsolka która pokrywa martwe konary dębów jaskrawymi pomarańczowo-żółtymi, mocno chropowatymi w dotyku rzędami cienkich tarczek.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Stereum_hirsutum.jpg?width=800" },
        new Grzyb { Id = 249, Nazwa = "Skórnik purpurowy", Rodzina = "Skórnikowate", Opis = "Groźny pasożyt sadów objawiający się jako malutkie dachóweczki o zadziwiająco jaskrawo fioletowych brzegach i gładkich szarych bokach z wierzchu owocników.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Chondrostereum_purpureum.jpg?width=800" },
        new Grzyb { Id = 250, Nazwa = "Powłocznik dębowy", Rodzina = "Powłocznikowate", Opis = "Wyrasta jako całkowicie spłaszczona niebieskawo-fioletowa, cienka jak kartka guma obleczona na powalonym dębowym drągu bez wykształcenia kapelusza.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Peniophora_quercina.jpg?width=800" },
        new Grzyb { Id = 251, Nazwa = "Mądziak psi", Rodzina = "Sromotnikowate", Opis = "Rozwija z okrągłego jaka bladożółtą, pustą wewnątrz rurkę zakończoną spiczastą, nieoderwaną główką pokrytą ciemnozielonym odpychającym szlamem na końcu.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Mutinus_caninus.jpg?width=800" },
        new Grzyb { Id = 252, Nazwa = "Okratek czerwony", Rodzina = "Sromotnikowate", Opis = "Tworzy pustą koszykową, krwistoczerwoną kulę ze zrośniętymi ząbkowanymi oczkami jak wyplecioną gąbkę i przeraźliwie śmierdzi gnijącymi warzywami.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Clathrus_ruber.jpg?width=800" },
        new Grzyb { Id = 253, Nazwa = "Czareczka długotrzonkowa", Rodzina = "Piórniczkowate", Opis = "Posiada kształt filigranowego zgrabnego szarego kieliszka opartego na stópce zakorzenionej w wilgotnej glebie po sam brzeg wypełnionego mszakiem.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Macroscypha_macropus.jpg?width=800" },
        new Grzyb { Id = 254, Nazwa = "Kustrzebka brunatna", Rodzina = "Kustrzebkowate", Opis = "Spore, faliste dołkowate ucha wyrastające w grupach przypominających ciemne miski porzucone na dnie brudnego lasu, o miąższu wodnistym lecz pozbawionym zapachu.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Peziza_badia.jpg?width=800" },
        new Grzyb { Id = 255, Nazwa = "Czarka austriacka", Rodzina = "Czarkowate", Opis = "Jeden z pierwszych symboli wiosny ukryty pod topniejącym śniegiem. Niewielki miseczkowaty grzyb którego wnętrze ma obłędny, świetlisto-czerwony pąs.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Sarcoscypha_austriaca.jpg?width=800" },
        new Grzyb { Id = 256, Nazwa = "Maczużnik bojowy", Rodzina = "Maczużnikowate", Opis = "Słynny 'grzyb zombie'. Pomarańczowe cienkie maczugi wyrastają prosto ze sparaliżowanych w ziemi ciał poczwarek ciem nakazując im opuścić dno lasu.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Cordyceps_militaris.jpg?width=800" },
        new Grzyb { Id = 257, Nazwa = "Maczużnik osi", Rodzina = "Ophiocordycipitaceae", Opis = "Pasożyt specjalizujący się w niszczeniu pojedynczych os leśnych z których martwych głów wylęga zaledwie parę milimetrów swojej żółtej pałeczki rodnej.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Ophiocordyceps_sphecocephala.jpg?width=800" },
        new Grzyb { Id = 258, Nazwa = "Piestrzenica jesienna", Rodzina = "Krążkownicowate", Opis = "Ukształtowana w przedziwne, brunatne, dwurożne worki, z daleka imitująca siodło, ale wydająca się jesienią i skrywająca potężne ilości lotnych kwasów rakotwórczych.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Gyromitra_infula.jpg?width=800" },
        new Grzyb { Id = 259, Nazwa = "Pierścieniak półkulisty", Rodzina = "Pierścieniakowate", Opis = "Żółtawy stożek porastający końskie odchody polne, mocno obślizgły z zewnątrz wydzielając stęchłą woń. Uważany za symbol słabo rozłożonych odchodów łąki.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Protostropharia_semiglobata.jpg?width=800" },
        new Grzyb { Id = 260, Nazwa = "Łysak wspaniały", Rodzina = "Hymenogastracae", Opis = "Masywne kępy mieniące się na złoto rosnące bezpośrednio u pni ściętych drzew uginają się od wagi łuskowatych grzybów o niemiłosiernie gorzkiej tonacji smakowej.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Gymnopilus_junonius.jpg?width=800" },
        new Grzyb { Id = 261, Nazwa = "Łysak plamisty", Rodzina = "Hymenogastracae", Opis = "Drobniejszy, ale za to dużo obficiej znoszący rdzawopomarańczowe blaszki rozsiewacz twardych gorzkich i suchych pędów wokół zwalonego na mech sosnowego drewna.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Gymnopilus_penetrans.jpg?width=800" },
        new Grzyb { Id = 262, Nazwa = "Monetka maślana", Rodzina = "Omphalotaceae", Opis = "Dość kruchy smaczny brązowy dzwon rzuca się w oczy w listopadzie a jego łodyga po zgnieceniu jest śluzowata w środku dając złudzenie wypełnienia roztopionym masłem.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Rhodocollybia_butyracea.jpg?width=800" },
        new Grzyb { Id = 263, Nazwa = "Łysiczka ceglasta", Rodzina = "Pierścieniakowate", Opis = "Niegdyś uznawana powszechnie jako trująca obok wiązkowej ale ma krwiście ceglasty wierzch ze swymi żółtawymi bokami. Bardzo długo ugotowana pozwala na jadalność w niektórych krajach.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Hypholoma_lateritium.jpg?width=800" },
        new Grzyb { Id = 264, Nazwa = "Pieniążek wrzecionowatotrzonowy", Rodzina = "Omphalotaceae", Opis = "Uderzający dziwactwem owocnik spod buków ze względu na niesamowity, twardy poplątany i zrośnięty korzeniowo trzon który tnie i zapętla swą strukturę ku podstawie.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Gymnopus_fusipes.jpg?width=800" },
        new Grzyb { Id = 265, Nazwa = "Czosnaczek szczypiorkowy", Rodzina = "Twardzioszkowate", Opis = "Starszy brat czosnaczka pospolitego. Jego czarny trzonek opanowuje ściółkę emitując niewyobrażalnie mocną ostrą cebulowo czosnkową eteryczną woń rozcinającą wzrok jak cebula.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Mycetinis_alliaceus.jpg?width=800" },
        new Grzyb { Id = 266, Nazwa = "Kępkowiec ciemnoszary", Rodzina = "Kępkowcowate", Opis = "Tworzy ciasne zrośnięte trzonkami grupki popielatych i szarych lśniących twardych lejków potrafiących przybierać ciężar kilku kilogramów pośrodku starych lasów z dębem.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Lyophyllum_fumosum.jpg?width=800" },
        new Grzyb { Id = 267, Nazwa = "Podblaszek zbutwiały", Rodzina = "Wodnichowate", Opis = "Maleńki biały grzyb wydostający się precyzyjnie prosto z zagrzebanych świerkowych opadłych starych, miękkich zepsutych szyszek i rozkładający nasiona iglaków.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Baeospora_myosura.jpg?width=800" },
        new Grzyb { Id = 268, Nazwa = "Szyszkówka świerkowa", Rodzina = "Fizalakowate", Opis = "Identyczna względem zbutwiałej szyszkówka jadalna, rosnąca dosłownie zaraz po marcowych roztopach śniegów i stanowiąca rarytas smaku prosto ze świerkowej szyszki.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Strobilurus_esculentus.jpg?width=800" },
        new Grzyb { Id = 269, Nazwa = "Stożkówka delikatna", Rodzina = "Gnojankowate", Opis = "Kruchutki i wąziutki żółto-biały stożek wybijający latem tuż pod krzewami, który zanika przed upływem nawet 12 godzin by pozostawić zaschnięty pył rozsypany na trawie.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Conocybe_apala.jpg?width=800" },
        new Grzyb { Id = 270, Nazwa = "Kruchaweczka zaroślowa", Rodzina = "Kruchaweczkowate", Opis = "Blady parasolik gęsto obsypany strzępami białej osłony, wybitnie smaczny chociaż rozsypujący się w palcach i niezwykle podatny na wodę, która rozmiękcza go w papkę.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Psathyrella_candolleana.jpg?width=800" },
        new Grzyb { Id = 271, Nazwa = "Kruchaweczka namakająca", Rodzina = "Kruchaweczkowate", Opis = "Związany z drewnem kępowy grzyb zmieniający radykalnie, higrofanicznie ubarwienie z ciepłego czekoladowego w rdzawy mat po krótkim deszczu i szybkim owianiu z rosy.", Jadalny = true, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Psathyrella_piluliformis.jpg?width=800" },
        new Grzyb { Id = 272, Nazwa = "Włośnianka rosista", Rodzina = "Hymenogastracae", Opis = "Wyrzuca przez kapelusz uderzający zapach surowej rzodkwi. Z blaszek, podobnie do kolczakówek, toczy rano setki łzawiących przezroczystych drobnych kropelek mętnej wody. Trujący.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Hebeloma_crustuliniforme.jpg?width=800" },
        new Grzyb { Id = 273, Nazwa = "Włośnianka musztardowa", Rodzina = "Hymenogastracae", Opis = "Należy do mocno toksycznej podgrupy o zapachu musztardowym uderzając mocną gliniastą barwą na mocnym sztywnym oszronionym w paski gładkim wielkim trzonie.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Hebeloma_sinapizans.jpg?width=800" },
        new Grzyb { Id = 274, Nazwa = "Zasłonak oszowny", Rodzina = "Zasłonakowate", Opis = "Stalowo lawendowy po fioletowy masywny korzeń o bulwie roztarty rozsiewa specyficzną woń naftaliny w szafie albo dojrzałych spleśniałych jabłek ze spichlerza leśniczego.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Cortinarius_traganus.jpg?width=800" },
        new Grzyb { Id = 275, Nazwa = "Rycerzyk oliwkowożółty", Rodzina = "Gąskowate", Opis = "Prześliczna jasnożółta, pękata i łuskowana głowa porastająca omszone mocno sosnowe kłody w głuszy na bagnach wydzielająca rzewny sosnowy cierpki aromat starych lasów.", Jadalny = false, ZdjecieUrl = "https://commons.wikimedia.org/wiki/Special:FilePath/Tricholomopsis_decora.jpg?width=800" },
